// lib/base58/alphabet.mjs
//
// The Bitcoin alphabet used by the `base58` package's default codec.  Confirmed
// against the reference program: digit 0 and the ambiguous letters O, I and l
// are absent, which is why '0', 'O', 'I' and 'l' are rejected on decode.

export const BITCOIN_ALPHABET =
  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

export const BASE = BigInt(BITCOIN_ALPHABET.length); // 58n

/** Byte value of the alphabet's first character, i.e. `alphabet[0:1]`. */
export const ZERO_CHAR_BYTE = BITCOIN_ALPHABET.charCodeAt(0); // 0x31 ('1')

/** byte value -> digit value, for decoding. */
const indexByByte = new Map();
for (let i = 0; i < BITCOIN_ALPHABET.length; i += 1) {
  indexByByte.set(BITCOIN_ALPHABET.charCodeAt(i), i);
}

/** Digit value for an ASCII byte, or `undefined` when not in the alphabet. */
export function digitForByte(byteValue) {
  return indexByByte.get(byteValue);
}

/** Alphabet character for a digit value. */
export function charForDigit(digit) {
  return BITCOIN_ALPHABET[digit];
}
