// lib/base58/int.mjs
//
// The integer layer of the codec: `b58encode_int` and `b58decode_int`.
//
// Both directions convert a batch of digits per big-integer operation.  A plain
// digit-at-a-time loop is quadratic in the operand size; batching keeps long
// inputs cheap without changing the digits produced.

import { PyValueError } from '../python/errors.mjs';
import { asciiCharRepr } from '../python/repr.mjs';
import { BASE, charForDigit, digitForByte } from './alphabet.mjs';

/** Digits handled per big-integer division/multiplication. */
const BATCH = 16;
const BATCH_BASE = BASE ** BigInt(BATCH); // 58 ** 16

/** Powers 58**0 .. 58**BATCH, for the trailing partial batch. */
const POWERS = [1n];
for (let i = 1; i <= BATCH; i += 1) POWERS.push(POWERS[i - 1] * BASE);

/**
 * `b58encode_int(i, default_one=...)`.
 *
 * @param {bigint} value non-negative
 * @param {{defaultOne?: boolean}} [options]
 * @returns {string}
 */
export function b58encodeInt(value, options = {}) {
  const defaultOne = options.defaultOne !== false;
  if (value === 0n) return defaultOne ? charForDigit(0) : '';

  const digits = []; // least significant first
  let rest = value;
  while (rest >= BATCH_BASE) {
    const quotient = rest / BATCH_BASE;
    let remainder = rest - quotient * BATCH_BASE;
    // The remainder is exactly BATCH digits wide (zero-padded on the left),
    // so emitting all BATCH of them keeps the positional value intact.
    for (let k = 0; k < BATCH; k += 1) {
      const next = remainder / BASE;
      digits.push(Number(remainder - next * BASE));
      remainder = next;
    }
    rest = quotient;
  }
  while (rest > 0n) {
    const next = rest / BASE;
    digits.push(Number(rest - next * BASE));
    rest = next;
  }

  let out = '';
  for (let i = digits.length - 1; i >= 0; i -= 1) out += charForDigit(digits[i]);
  return out;
}

/**
 * `b58decode_int(v)` for an already ASCII-encoded value.
 *
 * Raises the library's `ValueError: Invalid character {!r}` at the first byte
 * outside the alphabet, matching its left-to-right scan.
 *
 * @param {number[]} bytes
 * @returns {bigint}
 */
export function b58decodeInt(bytes) {
  let acc = 0n;
  let batch = 0n;
  let count = 0;
  for (const byteValue of bytes) {
    const digit = digitForByte(byteValue);
    if (digit === undefined) {
      throw new PyValueError(`Invalid character ${asciiCharRepr(byteValue)}`);
    }
    batch = batch * BASE + BigInt(digit);
    count += 1;
    if (count === BATCH) {
      acc = acc * BATCH_BASE + batch;
      batch = 0n;
      count = 0;
    }
  }
  if (count > 0) acc = acc * POWERS[count] + batch;
  return acc;
}

// lib/python/unicode.mjs
//
// Code-point level string helpers that reproduce the pieces of CPython's `str`
// behaviour this program depends on: `str.rstrip()`, `str.encode('ascii')` and
// `str.encode('utf-8')`.
//
// Byte sequences are represented as plain JavaScript arrays of integers in
// 0..255 — see lib/python/bytes.mjs.

import { PyUnicodeEncodeError } from './errors.mjs';

/**
 * Code points for which CPython's `str.isspace()` is true.  Established
 * empirically against the reference program (U+001B, U+180E, U+200B, U+2060 and
 * U+FEFF are deliberately absent — Python does not treat them as whitespace).
 */
const WHITESPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d,
  0x1c, 0x1d, 0x1e, 0x1f,
  0x20,
  0x85,
  0xa0,
  0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029,
  0x202f,
  0x205f,
  0x3000,
]);

export function isPythonSpace(codePoint) {
  return WHITESPACE.has(codePoint);
}

/** Split a string into its code points (surrogate pairs kept together). */
export function toCodePoints(text) {
  const points = [];
  for (const ch of text) points.push(ch.codePointAt(0));
  return points;
}

/** Equivalent of Python's `str.rstrip()` (no argument: strip all whitespace). */
export function rstrip(text) {
  const points = toCodePoints(text);
  let end = points.length;
  while (end > 0 && isPythonSpace(points[end - 1])) end -= 1;
  return points.slice(0, end).map((cp) => String.fromCodePoint(cp)).join('');
